use super::kit::*;
pub fn commands()->Vec<Command>{vec![Command{name:"export_color_pipeline_lut",description:"Bake explicit ordered pointwise color effects/managed transforms/nativeOCIO space or view steps into17/33/65.cube. No spatial/grain/masks, no automaticpipeline inference. Frozen time, explicitRGBdomain. Outputnotclipped.",mutates:false,
 schema:obj(vec![("steps",json!({"type":"array","minItems":1,"maxItems":64,"items":{"type":"object"}})),("path",s("output .cube")),("size",n("17/33/65 default33")),("time",n("frozenparameter time default0")),("domain_min",json!({"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3})),("domain_max",json!({"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3}))],&["steps","path"]),run:|_,a|{
 let o=a.as_object().ok_or("object required")?;for k in o.keys(){if !["steps","path","size","time","domain_min","domain_max"].contains(&k.as_str()){return Err(format!("unknown key {k}"))}}
 let steps=serde_json::from_value(a.get("steps").ok_or("steps required")?.clone()).map_err(|e|format!("invalidsteps (OCIO requiresnativefeature): {e}"))?;let n=a.get("size").map(|v|v.as_u64().ok_or("integer size required")).transpose()?.unwrap_or(33) as usize;let time=a.get("time").map(|v|v.as_f64().ok_or("numeric time required")).transpose()?.unwrap_or(0.);let arr=|k:&str,d:[f32;3]|->Result<[f32;3],String>{a.get(k).map(|v|serde_json::from_value(v.clone()).map_err(|e|e.to_string())).unwrap_or(Ok(d))};let c=crate::color::bake::Chain::new(steps,time)?;let l=c.bake(n,arr("domain_min",[0.;3])?,arr("domain_max",[1.;3])?)?;serde_json::to_value(c.write(&l,str_arg(a,"path")?)?).map_err(|e|e.to_string())
 }}]}
